import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Learning paths","description":"Pick by the problem you have now: use the assistant, then add it to your app, then ship.","frontmatter":{"title":"Learning paths","description":"Pick by the problem you have now: use the assistant, then add it to your app, then ship.","domain":"path","tags":["path"],"listed":false,"outline":false,"pageClass":"catalog-page","prev":false,"next":{"text":"Path 1 · Use AI tools","link":"/paths/productivity"}},"headers":[],"relativePath":"paths/index.md","filePath":"paths/index.md","lastUpdated":1788317563000}'),s={name:"paths/index.md"};function n(i,t,d,h,l,p){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="learning-paths" tabindex="-1">Learning paths <a class="header-anchor" href="#learning-paths" aria-label="Permalink to &quot;Learning paths&quot;">​</a></h1><p>Answer one question: <strong>which sentence is you right now?</strong></p><ol><li>“I am slow, and I do not know how to drive the assistant.” → Path 1</li><li>“I need the model inside my own product.” → Path 2</li><li>“The demo works; I cannot ship it or price it.” → Path 3</li></ol><p>The three paths <strong>stack</strong>. Default order is 1 → 2 → 3. Skip to 2 only if you already use a coding agent every day.</p><p>This is not a product manual (<a href="/products/">Products</a>) and not model internals (<a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a>).</p><h2 id="in-reading-order" tabindex="-1">In reading order <a class="header-anchor" href="#in-reading-order" aria-label="Permalink to &quot;In reading order&quot;">​</a></h2><h3 id="_1-use-ai-tools" tabindex="-1">1. Use AI tools <a class="header-anchor" href="#_1-use-ai-tools" aria-label="Permalink to &quot;1. Use AI tools&quot;">​</a></h3><p><strong>Problem</strong>: boilerplate by hand, docs by hand, half-day debugging.<br><strong>After</strong>: you can drive Cursor, Copilot, Claude, or Gemini on a real repo.<br><strong>Next</strong>: put a model in your app.</p><p><strong><a href="/paths/productivity.html">Start path 1</a></strong></p><h3 id="_2-add-ai-features" tabindex="-1">2. Add AI features <a class="header-anchor" href="#_2-add-ai-features" aria-label="Permalink to &quot;2. Add AI features&quot;">​</a></h3><p><strong>Problem</strong>: you can use the assistant, but your React / Vue app has no chat, search, or fill.<br><strong>After</strong>: API calls, streaming UI, RAG search.<br><strong>Need</strong>: path 1 habits; TypeScript.</p><p><strong><a href="/paths/integration.html">Start path 2</a></strong></p><h3 id="_3-build-ai-products" tabindex="-1">3. Build AI products <a class="header-anchor" href="#_3-build-ai-products" aria-label="Permalink to &quot;3. Build AI products&quot;">​</a></h3><p><strong>Problem</strong>: the demo is fine; production times out and the bill explodes.<br><strong>After</strong>: deploy, rate-limit, observe, cost, eval.<br><strong>Need</strong>: at least one working feature from path 2.</p><p><strong><a href="/paths/mastery.html">Start path 3</a></strong></p><h2 id="how-to-choose" tabindex="-1">How to choose <a class="header-anchor" href="#how-to-choose" aria-label="Permalink to &quot;How to choose&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You are here</th><th>Take</th></tr></thead><tbody><tr><td>Almost never used a coding agent</td><td>Path 1</td></tr><tr><td>Use one daily; need it in the product</td><td>Path 2</td></tr><tr><td>Already wired an API / RAG; need to ship</td><td>Path 3</td></tr></tbody></table>',17)])])}const f=e(s,[["render",n]]);export{b as __pageData,f as default};
